/**
 * note-prompt.mjs — shared editorial-note generation for The Stromata.
 *
 * One home for every part of note_draft generation, imported by both
 * `scripts/generate-note-drafts.mjs` (backfill / regeneration) and
 * `scripts/ingestion/fetch-texts.mjs` (Stage 2 inline). Keeping the prompt,
 * the anti-formula guards, and the critic loop here is deliberate: the two
 * callers used to carry byte-identical copies of `generateDraft` and
 * `trimToCompleteSentence`, which drifted apart the moment either changed.
 *
 * WHY THE CRITIC LOOP: a note is generated by a separate per-text API call
 * with no memory of the other ~230 notes, so the model regresses to the modal
 * realization of the prompt — the same dated-participle opener and the same
 * "Expect X rather than Y" closer every time. An audit of the live corpus
 * (Sept 2026) found the closer template on 70% of notes and the opener on 55%,
 * with whole single-author clusters near-interchangeable. The fixes here are
 * three: (1) a prompt that forbids the templated shapes and demands a
 * content-first opening; (2) a fresh-context critic call that scores each draft
 * and feeds specific gaps back for a rewrite; (3) optional sibling awareness so
 * notes in the same cluster are told what NOT to echo. A cheap regex guard also
 * rejects the known stock phrases outright before spending a critic call.
 *
 * The pure helpers (findBannedPhrases / endsOnCompleteSentence /
 * trimToCompleteSentence) take no API and are unit-tested in note-prompt.test.mjs.
 */

// The model id is functional config that already lived in both callers; it is
// centralized (not newly introduced) and overridable so a run can pin another.
export const NOTE_MODEL = process.env.NOTE_MODEL || 'claude-opus-4-7';

// ── The generation prompt ────────────────────────────────────────────────────
export const NOTE_PROMPT = `You are writing a brief editorial note for The Stromata, a curated library of out-of-print Christian theological texts. A reader arrives cold; tell them what they've found and why it is worth their time, as a knowledgeable guide would — never as a blurb writer, an academic, or a marketer.

LENGTH & SHAPE
- 3–4 sentences. Vary the rhythm: at least one sentence should be short. Do not settle into a uniform ~120-word paragraph — uniformity across notes is itself a tell.
- Return only the note. No preamble, no quotation marks around the whole thing, no trailing ellipsis. End on a complete sentence with a full stop, question mark, or exclamation mark. Never stop mid-thought.

OPEN WITH THE TEXT, NOT ITS METADATA
- Begin with the single most specific, concrete, or surprising thing in THIS text: a scene, an image, a claim it makes, a line it turns on, the occasion that provoked it. That specific thing is the note's reason to exist.
- Date, place, and circumstance may appear later, in a subordinate clause — never as the first words. Do NOT open with "Written in…", "Composed in…", "Delivered in…", or any "[verb] in [year], this [genre]…" formula.
- Do not begin with the author's name or the text's title.

DO NOT END ON A FORMULA
- Do NOT end with a sentence that begins "Expect…", "Read it…", "Read it as…", or "Read it slowly…", and do not tell the reader what kind of prose to brace for as a closing move.
- Avoid the closing contrast "X rather than Y" and "closer to X than Y". Let the note end on something true about the text, not an instruction about how to read it.

BANNED FLOURISHES (they read as machine-written)
- "would echo / would later / would shape / would become", "a century later", "point by point", "rewards slow/patient/attentive reading", "startlingly / strikingly modern / contemporary", "the pressure of … behind every clause", "aimed at the ear rather than the page", "thinking aloud among his books".
- Where a text genuinely founded a tradition or influenced a later figure, say so plainly and once — not as an inflated prophetic flourish.

Use a concrete biographical or textual detail where it illuminates. Specific always beats grand.`;

// ── Sibling-awareness clause ─────────────────────────────────────────────────
// Appended to the user message when other notes by the same author/collection
// already exist, so the generator is told what shapes NOT to repeat. This is
// the single strongest defence against near-interchangeable clusters.
export function siblingClause(siblingNotes = []) {
  const clean = siblingNotes.map((s) => (s || '').trim()).filter(Boolean).slice(0, 8);
  if (clean.length === 0) return '';
  return [
    '',
    'These notes already exist for other texts by the same author or in the same collection. Your note MUST NOT share an opening move or a closing move with any of them, and must foreground what is unique to THIS text rather than what it shares with its siblings:',
    ...clean.map((s, i) => `  (${i + 1}) ${s}`),
  ].join('\n');
}

// ── The critic prompt ────────────────────────────────────────────────────────
// A fresh-context reviewer. It sees only the note plus the text it introduces —
// never the generation prompt or the earlier attempts — so it cannot rationalize
// its own prior choices. Returns strict JSON.
export const CRITIC_PROMPT = `You are a ruthless editorial critic — the kind who edits back-cover copy for a top classics imprint (NYRB Classics, Penguin Classics) and wall text for a major museum. You are judging a single 3–4 sentence editorial note that introduces a Christian theological text to a general reader.

Judge ONLY the note against a top editorial-desk bar. Hunt for signs it was written by an AI reaching for the most likely words rather than by an editor who read THIS text and had one true thing to say.

Penalize hard:
- An opening built on date/place/circumstance metadata rather than something concrete in the text.
- A closing that instructs the reader how to read ("Expect…", "Read it as…") or leans on an "X rather than Y" contrast.
- Stock flourishes ("would echo/shape/become", "a century later", "rewards slow reading", "startlingly modern", etc.).
- A note that could be pasted onto any text of the same genre or author — i.e. no concrete, un-guessable detail specific to THIS text.

Reward: a genuinely specific opening, a concrete detail only someone engaging this text would write, a natural ending, varied sentence rhythm.

Return ONLY minified JSON, no prose, in exactly this shape:
{"score": <integer 1-10>, "leads_with_content": <bool>, "closer_is_formulaic": <bool>, "has_concrete_detail": <bool>, "generic_to_genre": <bool>, "issues": [<short strings>], "guidance": "<one or two sentences telling the writer what to change>"}

10 = indistinguishable from the best human-written classics-imprint copy. Be bold and honest, not safe.`;

// ── Anti-formula regex guard ─────────────────────────────────────────────────
// Cheap pre-filter: catches the loudest known tells so an obviously-templated
// draft is rejected before spending a critic call. Deliberately conservative —
// only phrases the audit found to be reliable markers, matched case-insensitively.
export const BANNED_PATTERNS = [
  { label: 'closer: "Expect…"', re: /(^|[.!?]\s+)expect\b[^.!?]*[.!?]?["'”’)*]*\s*$/i },
  { label: 'closer: "Read it…"', re: /(^|[.!?]\s+)read it\b/i },
  { label: 'contrast: "X rather than Y"', re: /\brather than\b/i },
  { label: 'contrast: "closer to X than Y"', re: /\bcloser to\b[^.!?]*\bthan\b/i },
  { label: 'flourish: "would echo/shape/become/later"', re: /\bwould (echo|later|soon|shape|become|prove|inspire)\b/i },
  { label: 'flourish: "a century later"', re: /\b(a|the)\s+centur(y|ies)\s+later\b/i },
  { label: 'flourish: "point by point"', re: /\bpoint by point\b/i },
  { label: 'flourish: "rewards … reading"', re: /\brewards?\b[^.!?]*\breading\b/i },
  { label: 'flourish: "startlingly/strikingly modern/contemporary"', re: /\b(startlingly|strikingly)\s+(modern|contemporary|relevant)\b/i },
  { label: 'opener: dated participle', re: /^(written|composed|delivered|preached|drawn|extracted|cast)\b[^.!?]*\b(in|around|during|near|between|shortly)\b/i },
];

/** Return the labels of every banned pattern the note trips (empty = clean). */
export function findBannedPhrases(note) {
  const text = (note || '').trim();
  if (!text) return [];
  return BANNED_PATTERNS.filter((p) => p.re.test(text)).map((p) => p.label);
}

/** True when the note ends on sentence-terminal punctuation (not mid-word). */
export function endsOnCompleteSentence(note) {
  return /[.!?]["'”’)*]?\s*$/.test((note || '').trim());
}

/**
 * Trim a note back to its last complete sentence. Used as a safety net when a
 * response is cut at max_tokens: it is better to drop an incomplete final
 * sentence than to ship "…assent to prop". Returns the text unchanged when it
 * already ends cleanly; returns '' when there is no complete sentence at all
 * (the caller then treats it as a generation failure rather than shipping it).
 */
export function trimToCompleteSentence(text) {
  const t = (text || '').trim();
  if (!t) return '';
  if (endsOnCompleteSentence(t)) return t;
  const lastEnd = Math.max(t.lastIndexOf('.'), t.lastIndexOf('!'), t.lastIndexOf('?'));
  if (lastEnd === -1) return '';
  return t.slice(0, lastEnd + 1).trim();
}

// ── Model plumbing ───────────────────────────────────────────────────────────

function buildUserMessage({ title, author, body, siblingNotes, critique }) {
  const parts = [
    `Title: ${title}`,
    `Author: ${author}`,
    '',
    (body || '').slice(0, 3000),
    siblingClause(siblingNotes),
  ];
  if (critique) {
    parts.push(
      '',
      'A previous draft was rejected by an editor. Do not repeat these problems; write a fresh note:',
      `  ${critique}`,
    );
  }
  return parts.filter((p) => p !== '').join('\n');
}

/** One generation call. Returns { text, truncated } with a clean-ending text. */
async function generateOnce({ anthropic, model, maxTokens, title, author, body, siblingNotes, critique }) {
  const message = await anthropic.messages.create({
    model,
    max_tokens: maxTokens,
    system: NOTE_PROMPT,
    messages: [{ role: 'user', content: buildUserMessage({ title, author, body, siblingNotes, critique }) }],
  });
  const raw = (message.content?.[0]?.text ?? '').trim();
  const truncated = message.stop_reason === 'max_tokens' || !endsOnCompleteSentence(raw);
  return { text: trimToCompleteSentence(raw), truncated };
}

/** Fresh-context critic call. Returns { score, issues, guidance, ... } or null. */
export async function critiqueNote({ anthropic, model = NOTE_MODEL, note, title, author, body }) {
  const userMessage = [
    `Text being introduced — Title: ${title}; Author: ${author}.`,
    'First lines of the text, so you can judge whether the note is specific to it:',
    (body || '').slice(0, 1500),
    '',
    'The editorial note to judge:',
    note,
  ].join('\n');

  const message = await anthropic.messages.create({
    model,
    max_tokens: 400,
    system: CRITIC_PROMPT,
    messages: [{ role: 'user', content: userMessage }],
  });
  const raw = (message.content?.[0]?.text ?? '').trim();
  try {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start === -1 || end === -1) return null;
    return JSON.parse(raw.slice(start, end + 1));
  } catch {
    return null;
  }
}

/**
 * Generate a note and improve it with a critic-in-the-loop, per the Chimala
 * design method: a fast/strong model writes, a fresh-context critic scores, and
 * a draft that fails the bar (or trips the regex guard) is regenerated with the
 * critique fed back. Returns the best draft seen across attempts.
 *
 * @param {{
 *   anthropic: import('@anthropic-ai/sdk').default,
 *   model?: string,
 *   criticModel?: string,
 *   title: string,
 *   author: string,
 *   body: string,
 *   siblingNotes?: string[],
 *   maxTokens?: number,
 *   maxAttempts?: number,
 *   scoreThreshold?: number,
 *   useCritic?: boolean,
 *   log?: (msg: string) => void,
 * }} opts
 * @returns {Promise<{ note: string, attempts: number, score: number|null, banned: string[], truncated: boolean }>}
 */
export async function generateNoteWithCritic({
  anthropic,
  model = NOTE_MODEL,
  criticModel = NOTE_MODEL,
  title,
  author,
  body,
  siblingNotes = [],
  maxTokens = 600,
  maxAttempts = 3,
  scoreThreshold = 8,
  useCritic = true,
  log = () => {},
}) {
  let critique = null;
  let best = { note: '', score: -1, banned: [], truncated: false };

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const { text, truncated } = await generateOnce({
      anthropic, model, maxTokens, title, author, body, siblingNotes, critique,
    });

    if (!text) {
      log(`    attempt ${attempt}: empty/uncompletable response, retrying`);
      critique = 'The previous response did not contain a complete note. Write a full 3–4 sentence note ending in a complete sentence.';
      continue;
    }

    const banned = findBannedPhrases(text);

    // Last attempt, or no critic requested: keep the best of what we have.
    if (!useCritic || attempt === maxAttempts) {
      if (banned.length === 0 && best.note) {
        // prefer an earlier clean, high-scoring draft over a final banned one
      } else if (text) {
        best = pickBetter(best, { note: text, score: banned.length === 0 ? 6 : 3, banned, truncated });
      }
      break;
    }

    const verdict = await critiqueNote({ anthropic, model: criticModel, note: text, title, author, body });
    const score = verdict?.score ?? null;
    best = pickBetter(best, { note: text, score: score ?? (banned.length === 0 ? 6 : 3), banned, truncated });

    if (banned.length === 0 && score !== null && score >= scoreThreshold) {
      log(`    attempt ${attempt}: accepted (score ${score})`);
      return { note: text, attempts: attempt, score, banned, truncated };
    }

    const issues = [
      banned.length ? `Remove these formulaic patterns: ${banned.join('; ')}.` : '',
      verdict?.guidance || '',
      Array.isArray(verdict?.issues) ? verdict.issues.join(' ') : '',
    ].filter(Boolean).join(' ');
    critique = issues || 'Make the note more specific to this text and avoid formulaic openings and closings.';
    log(`    attempt ${attempt}: score ${score ?? '—'}${banned.length ? `, banned: ${banned.join(', ')}` : ''} — regenerating`);
  }

  return { note: best.note, attempts: maxAttempts, score: best.score >= 0 ? best.score : null, banned: best.banned, truncated: best.truncated };
}

function pickBetter(a, b) {
  if (!a.note) return b;
  if (!b.note) return a;
  // Prefer clean (no banned phrases), then higher score.
  const aClean = a.banned.length === 0;
  const bClean = b.banned.length === 0;
  if (aClean !== bClean) return aClean ? a : b;
  return b.score > a.score ? b : a;
}
